package com.example.guitarmes.guitar;
import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*; import java.util.List; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.Mock; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.test.web.servlet.MockMvc; import org.springframework.test.web.servlet.setup.MockMvcBuilders; import com.example.guitarmes.assembly.AssemblyService; import com.example.guitarmes.process.*;
@ExtendWith(MockitoExtension.class) class GuitarViewControllerTest { @Mock GuitarService guitarService; @Mock ProcessService processService; @Mock AssemblyService assemblyService; MockMvc mvc; @BeforeEach void setUp(){mvc=MockMvcBuilders.standaloneSetup(new GuitarViewController(guitarService,processService,assemblyService)).build();}
@Test void list_containsBulkData() throws Exception { when(guitarService.getGuitarProgressList(processService,assemblyService)).thenReturn(List.of()); when(processService.getAvailableGuitarProcesses()).thenReturn(List.of()); mvc.perform(get("/guitars/view")).andExpect(status().isOk()).andExpect(view().name("guitar-list")).andExpect(model().attributeExists("guitars","processes")); }
}
